export const jurisdictionById = (id: string) => JURISDICTIONS.find((j) => j.id === id);
export const VERIFIED_JURISDICTIONS = JURISDICTIONS.filter((j) => j.verified);
export const SCAFFOLD_JURISDICTIONS = JURISDICTIONS.filter((j) => !j.verified);
